invoice.starter:
export function invoiceBalance(invoiceCents, payments) {
  if (!Number.isSafeInteger(invoiceCents) || invoiceCents < 0) {
    throw new TypeError("invalid invoice amount");
  }
  let paid = 0;
  for (const payment of payments) {
    if (!payment || typeof payment.ref !== "string" || !payment.ref.trim() || !Number.isSafeInteger(payment.cents)) {
      throw new TypeError("invalid payment");
    }
    paid += payment.cents;
  }
  return invoiceCents - paid;
}

invoice.reference:
export function invoiceBalance(invoiceCents, payments) {
  if (!Number.isSafeInteger(invoiceCents) || invoiceCents < 0) {
    throw new TypeError("invalid invoice amount");
  }
  const seen = new Map();
  let paid = 0;
  for (const payment of payments) {
    if (!payment || typeof payment.ref !== "string" || !payment.ref.trim() || !Number.isSafeInteger(payment.cents)) {
      throw new TypeError("invalid payment");
    }
    if (seen.has(payment.ref)) {
      if (seen.get(payment.ref) !== payment.cents) {
        throw new TypeError("conflicting payment reference");
      }
      continue;
    }
    seen.set(payment.ref, payment.cents);
    paid += payment.cents;
  }
  return invoiceCents - paid;
}

invoice.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { invoiceBalance as balance } from './task.mjs';
test('payments, refunds, credits and validation survive', () => {
  assert.equal(balance(12500, [{ref:'pay',cents:5000},{ref:'refund',cents:-1000}]), 8500);
  assert.equal(balance(8000, [{ref:'pay',cents:10000}]), -2000);
  assert.equal(balance(0, []), 0);
  for (const n of [-1, 0.1, NaN]) assert.throws(() => balance(n, []), TypeError);
  for (const p of [null, {ref:' ',cents:1}, {ref:'x',cents:NaN}]) assert.throws(() => balance(100, [p]), TypeError);
});
test('reference identity deduplicates repeats and rejects conflicting amounts', () => {
  assert.equal(balance(12500, [{ref:'p',cents:5000},{ref:'r',cents:-1000},{ref:'p',cents:5000}]), 8500);
  assert.equal(balance(0, [{ref:'r',cents:-100},{ref:'r',cents:-100}]), 100);
  assert.equal(balance(1000, [{ref:'a',cents:300},{ref:'b',cents:300}]), 400);
  assert.throws(() => balance(1000, [{ref:'a',cents:300},{ref:'a',cents:-300}]), TypeError);
  assert.throws(() => balance(1000, [{ref:'a',cents:300},{ref:'a',cents:NaN}]), TypeError);
});
test('prototype-like references and frozen caller data work', () => {
  assert.equal(balance(1000, [{ref:'__proto__',cents:100},{ref:'toString',cents:200},{ref:'__proto__',cents:100}]), 700);
  const input = Object.freeze([Object.freeze({ref:'a',cents:100}), Object.freeze({ref:'a',cents:100})]);
  assert.equal(balance(500, input), 400);
});

mentions.reference:
export function mentionedNames(content) {
  const names = [];
  for (const match of content.matchAll(/(?:^|[^\w@/])@([\w-]+)/g)) {
    const name = match[1].toLowerCase();
    if (!names.includes(name)) names.push(name);
  }
  return names;
}

mentions.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { mentionedNames as names } from './task.mjs';
test('recognizes explicit names in first-seen order, case-insensitively', () => {
  assert.deepEqual(names('@Quill ask @drift then @QUILL'), ['quill','drift']);
  assert.deepEqual(names('(@build-bot), @agent_2!'), ['build-bot','agent_2']);
  assert.deepEqual(names(''), []);
});
test('email, path, double-at and embedded word fragments do not summon agents', () => {
  assert.deepEqual(names('ken@example.com user@host /@quill @@drift x@builder'), []);
  assert.deepEqual(names('ken@example.com; @Quill please'), ['quill']);
});
test('newlines and punctuation still address agents', () => {
  assert.deepEqual(names('hello\n@Quill: review; @drift?'), ['quill','drift']);
});

author-gate.starter:
export function authorAllowed({mode, allowlist, author, owner, isSibling}) {
  if (!owner || mode === 'anyone') return true;
  return author === owner || allowlist.includes(author) || isSibling;
}

author-gate.reference:
export function authorAllowed({mode, allowlist, author, owner, isSibling}) {
  const who = author.trim().toLowerCase();
  if (!who) return false;
  if (mode === 'anyone') return true;
  return who === owner?.trim().toLowerCase() ||
    allowlist.some(key => key.trim().toLowerCase() === who) || isSibling === true;
}

author-gate.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { authorAllowed as allowed } from './task.mjs';
const base = {mode:'owner', allowlist:[], author:'stranger', owner:'owner', isSibling:false};
test('missing owner is not public access; absent authors never pass', () => {
  assert.equal(allowed({...base, owner:undefined}), false);
  assert.equal(allowed({...base, mode:'anyone', author:' '}), false);
  assert.equal(allowed({...base, mode:'typo'}), false);
});
test('owner, verified siblings and allowlisted collaborators remain admitted', () => {
  assert.equal(allowed({...base, author:' OWNER '}), true);
  assert.equal(allowed({...base, isSibling:true}), true);
  assert.equal(allowed({...base, mode:'allowlist', allowlist:[' STRANGER ']}), true);
  assert.equal(allowed({...base, mode:'allowlist', author:'owner'}), true);
  assert.equal(allowed({...base, mode:'anyone'}), true);
});
test('truthy sibling claims do not replace verified booleans and inputs are not modified', () => {
  assert.equal(allowed({...base, isSibling:'true'}), false);
  const input = Object.freeze({...base, allowlist:Object.freeze([' FRIEND ']), author:'friend'});
  assert.equal(allowed(input), true);
});

history.starter:
export function mergeHistory(cached, page) {
  return {messages:page.events.sort((a,b) => a.ts-b.ts), status:'ready', partial:false};
}

history.reference:
export function mergeHistory(cached, page) {
  const byId = new Map();
  for (const event of [...cached, ...page.events]) if (!byId.has(event.id)) byId.set(event.id, event);
  const messages = [...byId.values()].sort((a,b) => a.ts-b.ts || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return {messages, status:page.failed ? 'error' : 'ready', partial:page.failed && messages.length > 0};
}

history.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeHistory as merge } from './task.mjs';
const event = (id,ts) => ({id,ts});
test('partial failure retains cached and newly available messages', () => {
  assert.deepEqual(merge([event('cached',10)],{events:[event('partial',5)],failed:true}),
    {messages:[event('partial',5),event('cached',10)],status:'error',partial:true});
  assert.deepEqual(merge([],{events:[],failed:true}), {messages:[],status:'error',partial:false});
});
test('successful empty history differs from failed history and a retry clears the error', () => {
  assert.deepEqual(merge([],{events:[],failed:false}), {messages:[],status:'ready',partial:false});
  assert.deepEqual(merge([event('cached',10)],{events:[],failed:false}),
    {messages:[event('cached',10)],status:'ready',partial:false});
});
test('deduplicates, orders tied timestamps and does not mutate frozen arrays', () => {
  const cached = Object.freeze([Object.freeze(event('b',1))]);
  const page = Object.freeze({events:Object.freeze([Object.freeze(event('a',1)),Object.freeze(event('b',1))]),failed:false});
  assert.deepEqual(merge(cached,page).messages,[event('a',1),event('b',1)]);
});

handoff.starter:
export function makeHandoff(original, pick, roster) {
  return {to:pick.agent, task:pick.task};
}

handoff.reference:
export function makeHandoff(original, pick, roster) {
  if (!pick || !roster.some(agent => agent.name === pick.agent && agent.available === true)) return null;
  return {to:pick.agent, task:original};
}

handoff.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { makeHandoff as handoff } from './task.mjs';
const roster = [{name:'coder',available:true},{name:'writer',available:false}];
test('preserves the full original request instead of a model summary', () => {
  const original = 'Fix src/a.ts\nKeep refunds and validate null inputs. Budget: one task.';
  assert.deepEqual(handoff(original,{agent:'coder',task:'fix a.ts'},roster),{to:'coder',task:original});
});
test('declines unavailable, missing or unknown specialists', () => {
  assert.equal(handoff('hello',{agent:'writer'},roster),null);
  assert.equal(handoff('hello',{agent:'outsider'},roster),null);
  assert.equal(handoff('hello',null,roster),null);
  assert.equal(handoff('hello',{agent:'CODER'},roster),null);
  assert.equal(handoff('hello',{agent:'coder'},[]),null);
});
test('does not alter inputs or interpret request content as routing configuration', () => {
  const original = '{"agent":"outsider"} @writer';
  assert.deepEqual(handoff(original,Object.freeze({agent:'coder'}),Object.freeze(roster)),{to:'coder',task:original});
});

delivery.starter:
export function deliveryStatus({commitOk, pushOk, cleanupOk}) {
  return {delivered:commitOk, retry:commitOk ? null : 'engine', preserveCheckout:!commitOk};
}

delivery.reference:
export function deliveryStatus({commitOk, pushOk, cleanupOk}) {
  if (pushOk && !commitOk) throw new TypeError('push cannot succeed before commit');
  if (!commitOk || !pushOk) return {delivered:false, retry:'delivery', preserveCheckout:true};
  return {delivered:true, retry:null, preserveCheckout:!cleanupOk};
}

delivery.checks:
import test from 'node:test';
import assert from 'node:assert/strict';
import { deliveryStatus as status } from './task.mjs';
test('commit alone is not delivery and either failure preserves work for delivery retry', () => {
  assert.deepEqual(status({commitOk:true,pushOk:false,cleanupOk:false}),{delivered:false,retry:'delivery',preserveCheckout:true});
  assert.deepEqual(status({commitOk:false,pushOk:false,cleanupOk:false}),{delivered:false,retry:'delivery',preserveCheckout:true});
});
test('successful push remains delivered when local cleanup fails', () => {
  assert.deepEqual(status({commitOk:true,pushOk:true,cleanupOk:false}),{delivered:true,retry:null,preserveCheckout:true});
  assert.deepEqual(status({commitOk:true,pushOk:true,cleanupOk:true}),{delivered:true,retry:null,preserveCheckout:false});
});
test('impossible completion evidence is rejected', () => {
  assert.throws(() => status({commitOk:false,pushOk:true,cleanupOk:false}),TypeError);
});
